module tb;
    reg clk;
    reg load;
    reg ena;
    reg [1:0] amount;
    reg [63:0] data;
    wire [63:0] q;

    integer errors = 0;
    reg [63:0] expected_q;

    // Instantiate TopModule dut
    TopModule dut (
        .clk(clk),
        .load(load),
        .ena(ena),
        .amount(amount),
        .data(data),
        .q(q)
    );

    // Clock generator: 10ns period
    always #5 clk = ~clk;

    // Golden model task for expected behavior
    function [63:0] calc_next;
        input [63:0] current_q;
        input       i_load;
        input       i_ena;
        input [1:0] i_amount;
        input [63:0] i_data;
        begin
            if (i_load) begin
                calc_next = i_data;
            end else if (i_ena) begin
                case (i_amount)
                    2'b00: calc_next = {current_q[62:0], 1'b0};          // Shift left by 1
                    2'b01: calc_next = {current_q[55:0], 8'h00};         // Shift left by 8
                    2'b10: calc_next = {{1{current_q[63]}}, current_q[63:1]}; // Shift right (arithmetic) by 1
                    2'b11: calc_next = {{8{current_q[63]}}, current_q[63:8]}; // Shift right (arithmetic) by 8
                    default: calc_next = current_q;
                endcase
            end else begin
                calc_next = current_q;
            end
        end
    endfunction

    initial begin
        clk = 0;
        load = 0;
        ena = 0;
        amount = 2'b00;
        data = 64'h0;
        expected_q = 64'h0;

        #12; // Wait past first edge

        // Test 1: Synchronous Load with positive number
        @(posedge clk);
        load = 1; ena = 0; amount = 2'b00; data = 64'h0000_0000_1234_5678;
        expected_q = calc_next(expected_q, load, ena, amount, data);
        #1;
        if (q !== expected_q) errors = errors + 1;

