        @(posedge clk);
        load = 0; ena = 0; amount = 2'b00; data = 64'hFFFF_FFFF_FFFF_FFFF;
        expected_q = calc_next(expected_q, load, ena, amount, data);
        #1;
        if (q !== expected_q) errors = errors + 1;

        // Test 3: Shift left by 1
        @(posedge clk);
        load = 0; ena = 1; amount = 2'b00;
        expected_q = calc_next(expected_q, load, ena, amount, data);
        #1;
        if (q !== expected_q) errors = errors + 1;

        // Test 4: Shift left by 8
        @(posedge clk);
        load = 0; ena = 1; amount = 2'b01;
        expected_q = calc_next(expected_q, load, ena, amount, data);
        #1;
        if (q !== expected_q) errors = errors + 1;

        // Test 5: Load negative number (MSB = 1) for arithmetic shift testing
        @(posedge clk);
        load = 1; ena = 0; amount = 2'b00; data = 64'h8000_0000_0000_0001;
        expected_q = calc_next(expected_q, load, ena, amount, data);
        #1;
        if (q !== expected_q) errors = errors + 1;

        // Test 6: Shift right (arithmetic) by 1 (should sign-extend MSB)
        @(posedge clk);
        load = 0; ena = 1; amount = 2'b10;
        expected_q = calc_next(expected_q, load, ena, amount, data);
        #1;
        if (q !== expected_q) errors = errors + 1;

        // Test 7: Shift right (arithmetic) by 8 (should sign-extend MSB)
        @(posedge clk);
        load = 0; ena = 1; amount = 2'b11;
        expected_q = calc_next(expected_q, load, ena, amount, data);
        #1;
        if (q !== expected_q) errors = errors + 1;

        // Test 8: Simultaneous load and ena (load should take priority per spec "Loads shift register... instead of shifting")
        @(posedge clk);
        load = 1; ena = 1; amount = 2'b00; data = 64'hDEAD_BEEF_CAFE_BABE;
        expected_q = calc_next(expected_q, load, ena, amount, data);
        #1;
        if (q !== expected_q) errors = errors + 1;

        #10;
        if (errors == 0) begin
            $display("*** TEST RESULT: PASS ***");
        end else begin
            $display("*** TEST RESULT: FAIL ***");
        end
        $finish;
    end

endmodule
